import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;
import org.slf4j.MDC;

class QueryLoggingContextTest {

	private final Map<String, String> originalMdc = MDC.getCopyOfContextMap();

	@AfterEach
	void restoreMdc() {
		if (originalMdc == null) {
			MDC.clear();
		} else {
			MDC.setContextMap(originalMdc);
		}
	}

	@Test
	void snapshotCombinesExistingIdentifiersWithoutRetainingMutableContext() {
		MDC.put(QueryLoggingContext.SERVER_REQUEST_ID, "server-request");
		MDC.put(QueryLoggingContext.REPOSITORY_ID, "tracing-repo");
		MDC.put("trace_id", "trace-one");
		MDC.put("span_id", "span-one");
		MDC.put("authorization", "must-not-log");
		QueryCircuitBreakerHandle handle = new QueryCircuitBreakerHandle("server-123",
				QueryCircuitBreakerHandle.Source.SERVER, "actual-repo", "a1b2", 37L, null);
		Map<String, String> captured;
		try (QueryExecutionContext.Activation execution = QueryExecutionContext.activate(handle);
				QueryRequestContext.Activation query = QueryRequestContext.activate("query-request");
				QueryExplanationRequestContext.Activation explain = QueryExplanationRequestContext
						.activate("explanation")) {
			captured = QueryLoggingContext.capture();
		}
		MDC.put("trace_id", "trace-two");
		assertThat(captured).containsEntry("repositoryId", "actual-repo")
				.containsEntry("executionId", "server-123")
				.containsEntry("executionSource", "SERVER")
				.containsEntry("executionQueryHash", "a1b2")
				.containsEntry("executionStartTimeMillis", "37")
				.containsEntry("queryRequestId", "query-request")
				.containsEntry("explainRequestId", "explanation")
				.containsEntry("serverRequestId", "server-request")
				.containsEntry("traceId", "trace-one")
				.containsEntry("spanId", "span-one")
				.doesNotContainKey("authorization");
		assertThatThrownBy(() -> captured.put("repositoryId", "changed"))
				.isInstanceOf(UnsupportedOperationException.class);
	}

	@Test
	void scopesWorkWithoutAnMdcProviderAndRestoreNestedValues() {
		try (MockedStatic<MDC> noMdcProvider = mockStatic(MDC.class)) {
			Map<String, String> input = new HashMap<>();
			input.put(QueryLoggingContext.REPOSITORY_ID, "outer-repo");
			input.put("unrelated", "must-not-log");
			Map<String, String> captured;
			try (QueryLoggingContext.Activation outer = QueryLoggingContext.activateMdc(input)) {
				input.put(QueryLoggingContext.REPOSITORY_ID, "mutated");
				try (QueryLoggingContext.Activation inner = QueryLoggingContext.activateMdc(Map.of(
						QueryLoggingContext.REPOSITORY_ID, "inner-repo", QueryLoggingContext.TRACE_ID, "trace"))) {
					captured = QueryLoggingContext.capture();
				}
				assertThat(QueryLoggingContext.capture()).containsEntry("repositoryId", "outer-repo")
						.doesNotContainKeys("traceId", "unrelated");
			}
			assertThat(captured).containsEntry("repositoryId", "inner-repo").containsEntry("traceId", "trace");
			assertThat(QueryLoggingContext.capture()).doesNotContainKeys("repositoryId", "traceId", "unrelated");
		}
	}

	@Test
	void capturedAbsenceClearsWorkerIdentifiersAndRestoresItsPriorContext() throws Exception {
		MDC.remove(QueryLoggingContext.SERVER_REQUEST_ID);
		MDC.put(QueryLoggingContext.TRACE_ID, "submitted-trace");
		Map<String, String> context = QueryLoggingContext.captureMdc();
		MDC.put(QueryLoggingContext.TRACE_ID, "later-trace");
		try (ExecutorService worker = Executors.newSingleThreadExecutor()) {
			Map<String, String> observed = worker.submit(() -> {
				MDC.put(QueryLoggingContext.SERVER_REQUEST_ID, "previous-worker-request");
				MDC.put("unrelated", "worker-value");
				Map<String, String> captured;
				try (QueryLoggingContext.Activation ignored = QueryLoggingContext.activateMdc(context)) {
					captured = QueryLoggingContext.capture();
				}
				assertThat(MDC.get(QueryLoggingContext.SERVER_REQUEST_ID)).isEqualTo("previous-worker-request");
				assertThat(MDC.get("unrelated")).isEqualTo("worker-value");
				return captured;
			}).get(5, TimeUnit.SECONDS);
			assertThat(observed).containsEntry("traceId", "submitted-trace")
					.doesNotContainKeys("serverRequestId", "unrelated");
		}
	}

	@Test
	void concurrentRequestsKeepSeparateSnapshots() throws Exception {
		CyclicBarrier active = new CyclicBarrier(2);
		try (ExecutorService workers = Executors.newFixedThreadPool(2)) {
			Future<Map<String, String>> first = workers.submit(() -> captureAtBarrier("first", active));
			Future<Map<String, String>> second = workers.submit(() -> captureAtBarrier("second", active));
			assertThat(first.get(5, TimeUnit.SECONDS)).containsEntry("serverRequestId", "first");
			assertThat(second.get(5, TimeUnit.SECONDS)).containsEntry("serverRequestId", "second");
		}
	}

	private Map<String, String> captureAtBarrier(String requestId, CyclicBarrier active) throws Exception {
		try (QueryLoggingContext.Activation ignored = QueryLoggingContext.activateMdc(
				Map.of(QueryLoggingContext.SERVER_REQUEST_ID, requestId))) {
			active.await(5, TimeUnit.SECONDS);
			return QueryLoggingContext.capture();
		}
	}
}
